-- Generic Swedish foods from Livsmedelsverket (the Swedish Food Agency), shown in search
-- before branded Open Food Facts products. Nutrition is per 100 g.

alter table public.foods drop constraint foods_source_check;
alter table public.foods add constraint foods_source_check
  check (source in ('off', 'custom', 'slv'));

-- Livsmedelsverket's food number. A plain (non-partial) unique constraint, so the insert
-- below can be re-run on its own and skips rows that already exist.
alter table public.foods add column slv_number int unique;

